	open fun refreshReportedSpecies() {
		this.reported_species_names!!.clear()
		var p: Int = 0
		__L1@ while (p < this.n_pollutants()) {
			this.reported_species_names!!.push_back((this.pollutant_names!!.name_of(p))!!.Clone())
			p++
		}
		if (this.options!!.water_age) {
			this.reported_species_names!!.push_back(cpp.Str(cpp.R.Lit("__WATER_AGE__")))
		}
		if (this.options!!.heat_transport) {
			this.reported_species_names!!.push_back(cpp.Str(cpp.R.Lit("__TEMPERATURE__")))
		}
		(this.reactions!!.reported_species)!!.clear()
		var m: Int = 0
		__L2@ while (m < this.reactions!!.n_species()) {
			if ((!((this.reactions!!.report_enabled)!!.empty())) && (!((((this.reactions!!.report_enabled)!!.a!![m.toLong().toInt()]).toInt() and 0xFF) != 0))) {
				m++
				continue@__L2
			}
			(this.reactions!!.reported_species)!!.push_back(m)
			this.reported_species_names!!.push_back(((this.reactions!!.species_name)!!.a!![m.toLong().toInt()] as cpp.Str?)!!.Clone())
			m++
		}
	}

	open fun n_reported_species(): Int {
		return (this.reported_species_names!!.size()).toInt()
	}

	open fun logControlAction(e: SimulationContext_ControlLogEntry?) {
		if (java.lang.Long.compareUnsigned(this.control_log!!.size(), SimulationContext.kMaxControlLog) >= 0) {
			this.control_log_dropped++
			return
		}
		this.control_log!!.push_back(e!!.Clone())
	}

	open fun finalize_max_stats() {
		var k: Int = 0
		__L1@ while (k < SimulationContext.MAX_STATS) {
			val __o2 = SimulationContext_MaxStats()
			__o2.obj_type = 0
			__o2.index = -1
			__o2.value = -1.0
			(cpp.Ptr<SimulationContext_MaxStats?>(this.max_courant_crit, 0L)).get_Item_i(k)!!.MoveFrom(__o2)
			val __o3 = SimulationContext_MaxStats()
			__o3.obj_type = 1
			__o3.index = -1
			__o3.value = -1.0
			(cpp.Ptr<SimulationContext_MaxStats?>(this.max_flow_turns, 0L)).get_Item_i(k)!!.MoveFrom(__o3)
			val __o4 = SimulationContext_MaxStats()
			__o4.obj_type = 0
			__o4.index = -1
			__o4.value = 0.0
			(cpp.Ptr<SimulationContext_MaxStats?>(this.max_non_converged, 0L)).get_Item_i(k)!!.MoveFrom(__o4)
			k++
		}
		var rpt_steps: Long = this.routing_stats!!.report_steps
		if (rpt_steps > 2L) {
			var z: Double = 100.0 / (0.6666666666666666 * (rpt_steps - 2L).toDouble())
			var j: Int = 0
			__L5@ while (j < this.n_links()) {
				var x: Double = ((this.links!!.stat_flow_turns)!!.a!![j.toLong().toInt()]).toDouble() * z
				SimulationContext.updateMaxStats(cpp.Ptr<SimulationContext_MaxStats?>(this.max_flow_turns, 0L), 1, j, x)
				j++
			}
		}
		var step_count: Long = this.routing_stats!!.n_steps
		var dw: Boolean = this.options!!.routing_model == RoutingModel.DYNWAVE
		if (dw) {
			var j_2: Int = 0
			__L6@ while (j_2 < this.n_nodes()) {
				SimulationContext.updateMaxStats(cpp.Ptr<SimulationContext_MaxStats?>(this.max_non_converged, 0L), 0, j_2, ((this.nodes!!.stat_non_converged_count)!!.a!![j_2.toLong().toInt()]).toDouble() / step_count.toDouble())
				j_2++
			}
		}
		if (((!dw) || (this.options!!.variable_step == 0.0)) || (step_count == 0L)) {
			return
		}
		var inv_steps: Double = 1.0 / step_count.toDouble()
		var j_3: Int = 0
		__L7@ while (j_3 < this.n_nodes()) {
			var x_2: Double = (this.nodes!!.stat_time_courant_critical)!!.a!![j_3.toLong().toInt()] * inv_steps
			SimulationContext.updateMaxStats(cpp.Ptr<SimulationContext_MaxStats?>(this.max_courant_crit, 0L), 0, j_3, 100.0 * x_2)
			j_3++
		}
		var j_4: Int = 0
		__L8@ while (j_4 < this.n_links()) {
			var x_3: Double = (this.links!!.stat_time_courant_critical)!!.a!![j_4.toLong().toInt()] * inv_steps
			SimulationContext.updateMaxStats(cpp.Ptr<SimulationContext_MaxStats?>(this.max_courant_crit, 0L), 1, j_4, 100.0 * x_3)
			j_4++
		}
	}

	open fun reset() {
		val __o1 = SimulationContext_OutfallExports()
		__o1.water_m3 = cpp.VecD()
		__o1.reverse_m3 = cpp.VecD()
		__o1.heat_j = cpp.VecD()
