		this.outfall_exports!!.MoveFrom(__o1)
		this.runtime_coupling_used = false
		this.surface_outfall_link_limit!!.clear()
		val __o2 = SimulationContext_QualityOnlyInflow()
		__o2.vol = cpp.VecD()
		__o2.mass = cpp.VecD()
		__o2.msx = cpp.VecD()
		__o2.age_vol = cpp.VecD()
		__o2.temp_vol = cpp.VecD()
