		@JvmStatic fun New_mSimulationContext(p: SimulationContext?): SimulationContext? {
			var o: SimulationContext? = SimulationContext(cpp.Raw.V)
			o!!.__init_mSimulationContext(p)
			return o
		}

		@JvmStatic fun New(): SimulationContext? {
			var o: SimulationContext? = SimulationContext(cpp.Raw.V)
			o!!.__init_d()
			return o
		}

		@JvmStatic fun MoveNew(s: SimulationContext?): SimulationContext? {
			var o: SimulationContext? = SimulationContext(cpp.Raw.V)
			o!!.MoveFrom(s)
			return o
		}

		@JvmStatic fun updateMaxStats(arr: cpp.Ptr<SimulationContext_MaxStats?>?, obj_type: Int, idx: Int, value: Double) {
			var candidate: SimulationContext_MaxStats? = SimulationContext_MaxStats()
			candidate!!.obj_type = obj_type
			candidate!!.index = idx
			candidate!!.value = value
			var k: Int = 0
			__L1@ while (k < SimulationContext.MAX_STATS) {
				if (cpp.SysMath.Abs_d(candidate!!.value) > cpp.SysMath.Abs_d((arr!!.get_Item_i(k))!!.value)) {
					var tmp: SimulationContext_MaxStats? = SimulationContext_MaxStats.New_rMaxStats(arr!!.get_Item_i(k))
					(arr!!.get_Item_i(k))!!.Assign(candidate)
					candidate!!.Assign(tmp)
				}
				k++
			}
		}

	}
